/*
 * A107788  Numbers of the form (8^i)*(11^j), with i, j >= 0.
 * https://oeis.org/A107788
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = nth smallest positive integer of the form 8^i * 11^j (i,j
 *            ≥ 0)
 * Range:     u8 n <= 5, u16 n <= 18, u32 n <= 60, u64 n <= 218, u128 n <= 829,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by a classic two‑pointer merge of the
   sequences 8 * a(i) and 11 * a(i). */
#include <stdlib.h>
#include <stdbool.h>

seq_t a(idx_t n) {
    /* 0‑based table holding the sequence values (a(1) == table[0]) */
    static seq_t *table = NULL;
    static idx_t cap   = 0;
    static idx_t size  = 0;
    /* positions in the table to generate the next 8‑multiple and 11‑multiple */
    static idx_t i8    = 0;
    static idx_t i11   = 0;

    if (n == 0) return 0;          /* behaviour below offset is irrelevant */

    /* Grow the table until it contains at least n terms. */
    if (size < n) {
        /* Allocate or extend the table.  Use casted malloc/realloc for C++0x. */
        if (cap == 0) {
            cap = 64;
            table = (seq_t *)malloc(sizeof(seq_t) * cap);
        } else {
            while (cap < n) cap <<= 1;
            table = (seq_t *)realloc(table, sizeof(seq_t) * cap);
        }

        /* Initialise with the first term if the table was empty. */
        if (size == 0) {
            table[0] = (seq_t)1;   /* 8^0 * 11^0 */
            size = 1;
            i8 = 0;
            i11 = 0;
        }

        /* Generate further terms until we have n of them. */
        while (size < n) {
            seq_t v8  = table[i8] * (seq_t)8;
            seq_t v11 = table[i11] * (seq_t)11;
            seq_t next = (v8 < v11) ? v8 : v11;

            table[size++] = next;

            if (v8 == next) ++i8;
            if (v11 == next) ++i11;
        }
    }

    return table[n - 1];
}
